#!/usr/bin/env bash
# Makes this scenario's machine and project where the run starts. Generated by make_cases.py.
set -euo pipefail
here="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
key="/tmp/standin/by-dir/$(pwd -P | tr '/ ' '__')"
rm -rf "$key" && mkdir -p "$key"
cp -R "$here/state/." "$key/"
cp "$here/report.txt" "$key/report.txt"
chmod -R a+rwX "$key"
mkdir -p planning
if [ -d "$here/project" ]; then cp -R "$here/project/." .; fi
git init -q
git remote add origin https://github.com/someone/something.git
git add -A
git -c user.name=someone -c user.email=someone@example.org commit -q --allow-empty -m 'Planning documents'
